import React, { useState, useEffect } from 'react';
import { inventoryAPI } from '../services/api';

/**
 * Global Inventory Page
 * Shows aggregated inventory across all stores
 */
function GlobalInventory() {
  const [inventory, setInventory] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [filter, setFilter] = useState('all');

  useEffect(() => {
    fetchGlobalInventory();
  }, []);

  const fetchGlobalInventory = async () => {
    try {
      setLoading(true);
      const response = await inventoryAPI.getGlobalInventory();
      setInventory(response.data.data);
      setError(null);
    } catch (err) {
      setError('Failed to load global inventory');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const filteredInventory = inventory.filter(item => {
    if (filter === 'all') return true;
    return item.category === filter;
  });

  const categories = ['all', 'bikes', 'parts', 'accessories'];

  if (loading) return <div className="loading">Loading global inventory</div>;
  if (error) return <div className="error">{error}</div>;

  return (
    <div className="container">
      <h1 style={{ marginBottom: '2rem', color: '#667eea' }}>
        🌐 Global Inventory Overview
      </h1>

      {/* Summary Cards */}
      <div className="stats-grid">
        <div className="stat-card">
          <h3>Total Products</h3>
          <div className="value">{inventory.length}</div>
        </div>
        <div className="stat-card">
          <h3>Total Units</h3>
          <div className="value">
            {inventory.reduce((sum, item) => sum + item.totalQuantity, 0)}
          </div>
        </div>
        <div className="stat-card">
          <h3>Total Value</h3>
          <div className="value">
            ${inventory.reduce((sum, item) => sum + parseFloat(item.totalValue), 0).toFixed(2)}
          </div>
        </div>
        <div className="stat-card">
          <h3>Avg per Store</h3>
          <div className="value">
            {inventory.length > 0 
              ? Math.round(inventory.reduce((sum, item) => sum + item.totalQuantity, 0) / inventory[0].storeCount)
              : 0}
          </div>
        </div>
      </div>

      {/* Category Filter */}
      <div className="card">
        <div style={{ display: 'flex', gap: '1rem', marginBottom: '1rem' }}>
          <label style={{ fontWeight: 'bold' }}>Filter by Category:</label>
          {categories.map(cat => (
            <button
              key={cat}
              onClick={() => setFilter(cat)}
              className={filter === cat ? 'btn btn-primary' : 'btn btn-secondary'}
              style={{ padding: '0.4rem 1rem', fontSize: '0.9rem' }}
            >
              {cat.charAt(0).toUpperCase() + cat.slice(1)}
            </button>
          ))}
        </div>

        {/* Inventory Table */}
        <div className="table-container">
          <table>
            <thead>
              <tr>
                <th>Product</th>
                <th>Category</th>
                <th>SKU</th>
                <th>Total Quantity</th>
                <th>Price</th>
                <th>Total Value</th>
                <th>Stores</th>
                <th>Details</th>
              </tr>
            </thead>
            <tbody>
              {filteredInventory.map((item) => (
                <React.Fragment key={item.productId}>
                  <tr>
                    <td><strong>{item.productName}</strong></td>
                    <td>
                      <span className="badge badge-success">
                        {item.category}
                      </span>
                    </td>
                    <td style={{ fontSize: '0.85rem', color: '#666' }}>
                      {item.sku}
                    </td>
                    <td><strong>{item.totalQuantity}</strong></td>
                    <td>${item.price}</td>
                    <td><strong>${item.totalValue}</strong></td>
                    <td>{item.storeCount} stores</td>
                    <td>
                      <button
                        className="btn btn-secondary"
                        style={{ fontSize: '0.8rem', padding: '0.3rem 0.6rem' }}
                        onClick={() => {
                          const row = document.getElementById(`details-${item.productId}`);
                          row.style.display = row.style.display === 'none' ? 'table-row' : 'none';
                        }}
                      >
                        View
                      </button>
                    </td>
                  </tr>
                  <tr
                    id={`details-${item.productId}`}
                    style={{ display: 'none', background: '#f8f9fa' }}
                  >
                    <td colSpan="8">
                      <div style={{ padding: '1rem' }}>
                        <h4 style={{ marginBottom: '0.5rem', color: '#667eea' }}>
                          Store Distribution
                        </h4>
                        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '1rem' }}>
                          {item.stores.map((store, idx) => (
                            <div
                              key={idx}
                              style={{
                                padding: '0.8rem',
                                background: 'white',
                                borderRadius: '6px',
                                border: '1px solid #e9ecef'
                              }}
                            >
                              <p style={{ fontWeight: 'bold', marginBottom: '0.3rem' }}>
                                {store.storeName}
                              </p>
                              <p style={{ fontSize: '0.9rem' }}>
                                Quantity: <strong>{store.quantity}</strong>
                              </p>
                              {store.needsRestock && (
                                <span className="badge badge-danger" style={{ marginTop: '0.3rem' }}>
                                  Low Stock
                                </span>
                              )}
                            </div>
                          ))}
                        </div>
                      </div>
                    </td>
                  </tr>
                </React.Fragment>
              ))}
            </tbody>
          </table>
        </div>

        {filteredInventory.length === 0 && (
          <div className="empty-state">
            <p>No products found in this category</p>
          </div>
        )}
      </div>

      <button
        onClick={fetchGlobalInventory}
        className="btn btn-primary"
        style={{ marginTop: '1rem' }}
      >
        🔄 Refresh Data
      </button>
    </div>
  );
}

export default GlobalInventory;

// Made with Bob
